#include "ignore.h"

#include <string>

#include "clang/AST/Decl.h"

#include "../frontend/classify.h"
#include "code_sink.h"
#include "emit.h"

namespace tapa::cc {

void IgnoreBackend::EmitStreamPort(const PortContext& p, CodeSink& out) const {
  EmitDummyStreamRW(p.param, p.kind, out, /*qdma=*/false);
}

void IgnoreBackend::EmitMmapPort(const PortContext& p, CodeSink& out) const {
  EmitDummyMmapOrScalarRW(p.param, p.kind, out);
}

void IgnoreBackend::EmitAsyncMmapPort(const PortContext& p,
                                      CodeSink& out) const {
  EmitDummyMmapOrScalarRW(p.param, p.kind, out);
}

void IgnoreBackend::EmitScalarPort(const PortContext& p, CodeSink& out) const {
  EmitDummyMmapOrScalarRW(p.param, p.kind, out);
}

void IgnoreBackend::RewriteTaskFunc(const TaskModel& task, bool /*is_top*/,
                                    clang::Rewriter& rewriter) const {
  const clang::FunctionDecl* func = task.def;
  if (!func->hasBody()) return;
  // Replace the body with a shell of dummy port reads/writes only.
  CodeSink sink;
  for (const clang::ParmVarDecl* param : func->parameters()) {
    EmitPortPreamble(
        PortContext{param, ClassifyTapaType(param), TaskLevel::kLower, false},
        sink);
    sink.Line("");  // blank line between parameters (and a trailing newline)
  }
  rewriter.ReplaceText(func->getBody()->getSourceRange(),
                       "{\n" + sink.Str() + "}\n");
}

void IgnoreBackend::StripOtherTask(const clang::FunctionDecl* /*func*/,
                                   clang::Rewriter& /*rewriter*/) const {
  // The ignore shell leaves other task functions untouched (unlike the Xilinx
  // backend); only the ignored task becomes a shell and helpers are cleared.
}

void IgnoreBackend::RewriteHelperFunc(const clang::FunctionDecl* func,
                                      clang::Rewriter& rewriter) const {
  // Clear non-task helper bodies in the ignore shell.
  if (func->hasBody()) {
    rewriter.ReplaceText(func->getBody()->getSourceRange(), "{}\n");
  }
}

}  // namespace tapa::cc
#ifndef TAPA_CODEGEN_IGNORE_H_
#define TAPA_CODEGEN_IGNORE_H_

#include <string_view>

#include "backend.h"

namespace tapa::cc {

// The "ignore" backend: a task marked [[tapa::target("ignore")]] is a black box
// the user supplies RTL for, so tapacc emits only a shell whose ports survive
// dead-code elimination (dummy reads/writes) and whose body is otherwise empty.
class IgnoreBackend final : public Backend {
 public:
  std::string_view Name() const override { return "ignore"; }

  // Ignore never rewrites signatures (no mmap -> offset).
  void RewriteSignature(const TaskModel&, bool,
                        clang::Rewriter&) const override {}
  void RewriteTaskFunc(const TaskModel& task, bool is_top,
                       clang::Rewriter& rewriter) const override;
  void StripOtherTask(const clang::FunctionDecl* func,
                      clang::Rewriter& rewriter) const override;
  void RewriteHelperFunc(const clang::FunctionDecl* func,
                         clang::Rewriter& rewriter) const override;
  // Loop attributes vanish with the replaced body; nothing to lower.
  void LowerPipeline(int, const clang::Stmt*, clang::Rewriter&) const override {
  }
  void LowerUnroll(int, const clang::Stmt*, clang::Rewriter&) const override {}

 protected:
  void EmitStreamPort(const PortContext&, CodeSink&) const override;
  void EmitMmapPort(const PortContext&, CodeSink&) const override;
  void EmitAsyncMmapPort(const PortContext&, CodeSink&) const override;
  void EmitScalarPort(const PortContext&, CodeSink&) const override;
};

}  // namespace tapa::cc

#endif  // TAPA_CODEGEN_IGNORE_H_

