 1	#ifndef TAPA_FRONTEND_CLASSIFY_H_
 2	#define TAPA_FRONTEND_CLASSIFY_H_
 3	
 4	#include "clang/AST/Decl.h"
 5	#include "clang/AST/Expr.h"
 6	#include "clang/AST/Type.h"
 7	
 8	namespace tapa::cc {
 9	
10	// Structural classification of a task-parameter (or argument) type against the
11	// fixed set of TAPA types. Replaces the old regex matching on stringified
12	// qualified names (`IsTapaType(x, "((async_)?mmaps|hmap)")`): a type like
13	// `tapa::mmap_wrapper` can never be misread, and there is no regex surface.
14	enum class TapaKind {
15	  kNotTapa,  // any non-TAPA type: treated as a scalar port
16	
17	  // stream interfaces (task ports)
18	  kIStream,
19	  kOStream,
20	  kIStreams,
21	  kOStreams,
22	
23	  // stream instances (FIFOs declared inside an upper task; not ports)
24	  kStream,
25	  kStreams,
26	
27	  // memory-mapped interfaces
28	  kMmap,
29	  kMmaps,
30	  kAsyncMmap,
31	  kImmap,
32	  kOmmap,
33	  kHmap,
34	
35	  // special markers
36	  kTask,        // tapa::task (the invoke builder)
37	  kSeq,         // tapa::seq
38	  kExecutable,  // tapa::executable
39	};
40	
41	// Classify a type, peeling lvalue-references and template-parameter
42	// substitutions so `tapa::mmap<T>&` and a substituted `T` both reduce to the
43	// underlying record.
44	TapaKind ClassifyTapaType(clang::QualType type);
45	
46	inline TapaKind ClassifyTapaType(const clang::ParmVarDecl* param) {
47	  return ClassifyTapaType(param->getType());
48	}
49	inline TapaKind ClassifyTapaType(const clang::Expr* expr) {
50	  return ClassifyTapaType(expr->getType());
51	}
52	
53	// --- category predicates (enum checks, no strings) ---
54	
55	// istream / ostream / istreams / ostreams (any stream *port*).
56	constexpr bool IsStreamInterface(TapaKind k) {
57	  return k == TapaKind::kIStream || k == TapaKind::kOStream ||
58	         k == TapaKind::kIStreams || k == TapaKind::kOStreams;
59	}
60	// istreams / ostreams (an array of streams).
61	constexpr bool IsStreamArray(TapaKind k) {
62	  return k == TapaKind::kIStreams || k == TapaKind::kOStreams;
63	}
64	constexpr bool IsInputStream(TapaKind k) {
65	  return k == TapaKind::kIStream || k == TapaKind::kIStreams;
66	}
67	constexpr bool IsOutputStream(TapaKind k) {
68	  return k == TapaKind::kOStream || k == TapaKind::kOStreams;
69	}
70	// stream / streams (a FIFO *instance*, declared inside an upper task).
71	constexpr bool IsStreamInstance(TapaKind k) {
72	  return k == TapaKind::kStream || k == TapaKind::kStreams;
73	}
74	// mmap / mmaps / async_mmap / immap / ommap / hmap.
75	constexpr bool IsMmapInterface(TapaKind k) {
76	  return k == TapaKind::kMmap || k == TapaKind::kMmaps ||
77	         k == TapaKind::kAsyncMmap || k == TapaKind::kImmap ||
78	         k == TapaKind::kOmmap || k == TapaKind::kHmap;
79	}
80	constexpr bool IsAsyncMmap(TapaKind k) { return k == TapaKind::kAsyncMmap; }
81	// An array-shaped interface (expands to N wires): *streams, mmaps, hmap.
82	constexpr bool IsArrayInterface(TapaKind k) {
83	  return IsStreamArray(k) || k == TapaKind::kMmaps || k == TapaKind::kHmap;
84	}
85	
86	// The canonical serialized category ("cat") for a port/arg, e.g. "istream",
87	// "mmap", "scalar". Centralized with the enum; the values are the stable
88	// `ArgCategory` strings the graph schema keeps regardless of the tapa-ir
89	// rename.
90	const char* TapaKindCat(TapaKind k);
91	
92	}  // namespace tapa::cc
93	
94	#endif  // TAPA_FRONTEND_CLASSIFY_H_

