10	
11	namespace tapa::cc {
12	
13	std::string GenerateWrapper(const TaskModel& task, const Backend& backend,
14	                            clang::ASTContext& ctx) {
15	  // Suppress the tag keyword ("class"/"struct") so the printed parameter types
16	  // match the header the vendor toolchain sees.
17	  clang::PrintingPolicy policy = ctx.getPrintingPolicy();
18	  policy.SuppressTagKeyword = true;
19	
20	  const auto params = task.def->parameters();
21	
22	  std::string code = "\n\nvoid " + task.name + "(";
23	  for (unsigned i = 0; i < params.size(); ++i) {
24	    if (i > 0) code += ", ";
25	    code += params[i]->getType().getAsString(policy) + " " +
26	            params[i]->getNameAsString();
27	  }
28	  code += ") {\n";
29	
30	  // Lower-level interface preamble for each concrete port (2-space indented,
31	  // no blank separators -- matching the old wrapper layout).
32	  CodeSink sink;
33	  for (const clang::ParmVarDecl* param : params) {
34	    backend.EmitPortPreamble(
35	        PortContext{param, ClassifyTapaType(param), TaskLevel::kLower, false},
36	        sink);
37	  }
38	  for (const std::string& line : sink.Lines()) {
39	    code += "  " + line + "\n";
40	  }
41	
42	  // Call the actual templated function by its readable (templated) name.
43	  code += "  " + task.readable_name + "(";
44	  for (unsigned i = 0; i < params.size(); ++i) {
45	    if (i > 0) code += ", ";
46	    code += params[i]->getNameAsString();
47	  }
48	  code += ");\n}\n";
49	  return code;
50	}
51	
52	void InsertWrapper(const TaskModel& task, const Backend& backend,
53	                   clang::ASTContext& ctx, clang::Rewriter& rewriter) {
54	  if (task.invoker == nullptr) return;
55	  rewriter.InsertTextAfterToken(task.invoker->getEndLoc(),
56	                                GenerateWrapper(task, backend, ctx));
57	}
58	
59	}  // namespace tapa::cc

