   106	/// Apply the raw metrics reported by HLS to a task.
   107	///
   108	/// `clock_period` stores the achieved estimate, not the requested target.
   109	/// `total_area` is cleared because it is either re-populated by optional
   110	/// out-of-context synthesis or derived recursively from `self_area` by report
   111	/// and topology consumers.
   112	fn apply_hls_metrics(task: &mut Task, report: &CsynthReport) {
   113	    task.clock_period
   114	        .clone_from(&report.estimated_clock_period_ns);
   115	    task.self_area.clear();
   116	    task.total_area.clear();
   117	    for (key, value) in &report.area {
   118	        if let Ok(value) = value.parse::<i64>() {
   119	            task.self_area.insert(key.clone(), Value::from(value));
   120	        } else {
   121	            task.self_area
   122	                .insert(key.clone(), Value::String(value.clone()));
   123	        }
   124	    }
   125	}
   126	
   127	/// Build the HLS CFLAGS: the analyzer-stored `graph_cflags` (so
   128	/// `-isystem <tapa-lib>` etc. are forwarded into HLS) followed by the
   129	/// `-DTAPA_TARGET_*` defines and a `-I <tapa-extra-runtime-include>` entry
   130	/// when the resource can be resolved ("WORKAROUND: Vitis HLS requires -I or
   131	/// gflags cannot be found..." branch).
   132	fn build_hls_cflags(graph_cflags: &[String], remote: bool) -> Vec<String> {
   133	    // HLS cflags = the analyzer-stored graph cflags followed by
   134	    // `get_tapacc_cflags()`, so HLS sees the user's own `-I` / `-D`
   135	    // entries plus the tapa-lib / vendor-include resolution.
   136	    let mut flags: Vec<String> = graph_cflags.to_vec();
   137	    // Remote HLS substitutes `get_tapacc_cflags()` (local
   138	    // vendor/stdlib paths) with `get_remote_hls_cflags()` when
   139	    // `~/.taparc` is active — the
   140	    // remote host ships its own vendor headers via `settings64.sh`,
   141	    // and a host-specific macOS `__assert_rtn` remap is added so
   142	    // macOS → Linux remote synth does not mis-expand assert() into
   143	    // `__assert_rtn(func,file,line,expr)`.
   144	    if remote {
   145	        flags.extend(get_remote_hls_cflags());
   146	    } else {
   147	        flags.extend(get_tapacc_cflags(false));
   148	    }
   149	    flags.push("-DTAPA_TARGET_DEVICE_".to_string());
   150	    flags.push("-DTAPA_TARGET_XILINX_HLS_".to_string());
   151	    // Vitis HLS requires `-I` (not `-isystem`) to locate gflags during build.
   152	    if let Ok(p) = find_resource("tapa-extra-runtime-include") {
   153	        flags.push(format!("-I{}", p.display()));
   154	    }
   155	    flags
   156	}
