/// and the helper returns an empty vector.
fn find_external_lib_in_runfiles() -> Vec<PathBuf> {
    let anchor = std::env::var_os("TAPA_CLI_SEARCH_ANCHOR")
        .map(PathBuf::from)
        .or_else(|| std::env::current_exe().ok())
