  9	static ARRAY_NAME_WITH_SUFFIX_RE: LazyLock<Regex> =
 10	    LazyLock::new(|| Regex::new(r"^([a-zA-Z_]\w*)\[(\d+)\]([a-zA-Z_]\w*)?$").unwrap());
 11	
 12	/// Collapse `name[idx]` into `name_{idx}`.
 13	///
 14	/// The frontend spells the channels of an array interface (`mmaps`,
 15	/// `streams`) `name[i]`, and the brackets are load-bearing in the graph --
 16	/// they let consumers recover which logical argument a channel belongs to.
 17	/// Every projection to an RTL identifier collapses them, so this lives here,
 18	/// on the schema, rather than in any one consumer: `tapa-codegen`,
 19	/// `tapa pack` and `frt-cosim` must all agree on the name a port binds to.
 20	#[must_use]
 21	pub fn sanitize_array_name(name: &str) -> String {
 22	    ARRAY_NAME_WITH_SUFFIX_RE.captures(name).map_or_else(
 23	        || name.to_owned(),
 24	        |caps| {
 25	            format!(
 26	                "{}_{}{}",
 27	                &caps[1],
 28	                &caps[2],
 29	                caps.get(3).map_or("", |m| m.as_str())
 30	            )
 31	        },
 32	    )
 33	}
 34	
 35	/// Convert a frontend name into a plain Verilog identifier.
 36	///
 37	/// Array channels keep their established `foo[3]` to `foo_3` spelling;
 38	/// remaining characters that Verilog identifiers cannot contain become `_`.
 39	#[must_use]
 40	pub fn sanitize_identifier_name(name: &str) -> String {
 41	    let name = sanitize_array_name(name);
 42	    let mut out = String::with_capacity(name.len());
 43	    for (index, character) in name.chars().enumerate() {
 44	        let valid = character.is_ascii_alphanumeric() || matches!(character, '_' | '$');
 45	        if index == 0 && character.is_ascii_digit() {
 46	            out.push('_');
 47	        }
 48	        out.push(if valid { character } else { '_' });
 49	    }
 50	    out
 51	}
