 1	//! Per-task synthesis policy.
 2	
 3	use serde::{Deserialize, Serialize};
 4	
 5	/// Per-task synthesis policy.
 6	///
 7	/// The pipeline only distinguishes `Ignore` (skip synthesis) from `Hls`
 8	/// (synthesize with Vitis HLS). Serializes as the wire strings `"hls"` /
 9	/// `"ignore"`; any other value is a hard deserialize error. Distinct from
10	/// the flow-level [`crate::Target`] (`"xilinx-vitis"` / `"xilinx-hls"`),
11	/// which lives once at the graph root.
12	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
13	#[serde(rename_all = "lowercase")]
14	pub enum SynthTarget {
15	    /// `"hls"` — synthesize with Vitis HLS.
16	    Hls,
17	    /// `"ignore"` — skip synthesis (custom-RTL / passthrough tasks).
18	    Ignore,
19	}
20	
21	#[cfg(test)]
22	mod tests {
23	    use super::*;
24	
25	    #[test]
26	    fn hls_round_trips() {
27	        let json = serde_json::to_string(&SynthTarget::Hls).expect("serialize");
28	        assert_eq!(json, r#""hls""#);
29	        let back: SynthTarget = serde_json::from_str(&json).expect("deserialize");
30	        assert_eq!(back, SynthTarget::Hls);
31	    }
32	
33	    #[test]
34	    fn ignore_round_trips() {
35	        let json = serde_json::to_string(&SynthTarget::Ignore).expect("serialize");
36	        assert_eq!(json, r#""ignore""#);
37	        let back: SynthTarget = serde_json::from_str(&json).expect("deserialize");
38	        assert_eq!(back, SynthTarget::Ignore);
39	    }
40	
41	    #[test]
42	    fn unknown_value_rejected() {
43	        // The old flow-derived task target (e.g. `"xilinx_vitis"`) is no
44	        // longer a valid per-task synth policy: it must be rejected, not
45	        // preserved. tapacc emits `"hls"` / `"ignore"` only.
46	        assert!(
47	            serde_json::from_str::<SynthTarget>(r#""xilinx_vitis""#).is_err(),
48	            "unknown synth policy must be rejected",
49	        );
50	    }
51	}

