cd /home/dotkrnl/tapa && python - <<'PY'
import re,glob,os
# crude check for declarations in headers and references in cpp
files=glob.glob('tapacc/**/**/*.h',recursive=True)+glob.glob('tapacc/**/*.h',recursive=True)
# include only existing
funcs=[]
for f in files:
    if 'BUILD' in f or 'build_program.h' in f: pass
    with open(f) as fp:
        for ln,l in enumerate(fp,1):
            m=re.match(r'\s*([\w:<>::~]+)\s+([A-Za-z_][A-Za-z0-9_:]*)\s*\(',l)
            if m and '//' not in l:
                name=m.group(2)
                if name in {'if','for','while','while','return','sizeof'}: continue
                if name.startswith('std') or name.startswith('T'): pass
                if '(' in l and ')' in l and (';' in l or '{' in l):
                    if name not in {'if','switch'}:
                        if name in {'ClassifyTapaType','GetTemplateArg','GetTemplateArgAsInt','BuildPorts'}:
                            pass
                        if name and not name.startswith(('llvm::','clang::','std::')):
                            funcs.append((name,f,ln,l.strip()))

# unique names top 200 maybe
seen={}
for name,f,ln,l in funcs:
    if name in seen: continue
    seen[name]=(f,ln,l)
# check reference in non-header non-test cpp except tests
cpp=glob.glob('tapacc/**/*.cpp',recursive=True)
for name,(f,ln,l) in list(seen.items()):
    used=False
    for c in cpp:
        if 'test' in c: continue
        txt=open(c).read()
        if re.search(r'\b'+re.escape(name)+r'\b',txt):
            used=True;break
    if not used and not name.endswith(('_h','_H_')):
        # skip header guards maybe
        if any(x in name for x in ['TapaKind','OffsetName','ArrayElemOffset','ArrayNameAt','FifoVar','PeekVar','kMangledPrefix']):
            pass
        # print likely unused symbol declared in header only
        if name in ['TapaKindCat','BuildPorts','GetTemplateArg','TemplateArgName','TemplateArgAsInt','IntTemplateArg','BitWidth']:
            pass
        # too noisy; ignore

print('done',len(seen))
PY

